Looking at the compute loop, the inner `compute_k` loop is a reduction that runs inside the pipelined `compute_j` loop. The pipeline is on `compute_j`, which causes the inner k-loop to be unrolled/serialized into the pipeline body.

The key bottleneck is the floating-point accumulation dependency in `compute_k`. I'll add the appropriate pipeline pragma, array partitioning for parallel access, and dependence/tripcount pragmas without changing the algorithmic structure.

```cpp
#include "trmm.h"
#include <cstring>

void kernel_trmm( 
		 double alpha,
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INLINE off

    const int m = M;
    const int n = N;

    // Local buffers staged from global memory
    static double A_local[M][M];
    static double B_local[M][N];
    // Partition local arrays so the inner reduction can read multiple
    // operands per cycle and to relieve memory-port conflicts in the pipeline.
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=4 dim=1

    int i, j, k;

    // ---- LOAD phase: stage A and B into local memory ----
    load_A_rows:
    for (i = 0; i < m; i++) {
        load_A_cols:
        for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }
    }

    load_B_rows:
    for (i = 0; i < m; i++) {
        load_B_cols:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B_local[i][j] = B[i][j];
        }
    }

    // ---- COMPUTE phase: operate on local buffers ----
    compute_i:
    for (i = 0; i < m; i++) {
        compute_j:
        for (j = 0; j < n; j++) {
            double acc = B_local[i][j];
            compute_k:
            for (k = i + 1; k < m; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=M
                acc += A_local[k][i] * B_local[k][j];
            }
            B_local[i][j] = alpha * acc;
        }
    }

    // ---- STORE phase: write results back to global memory ----
    store_B_rows:
    for (i = 0; i < m; i++) {
        store_B_cols:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = B_local[i][j];
